INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-36','exam-sg','労働者派遣法','standard','single_choice','【平成30年度 春期 午前 問36】労働者派遣法に照らして，派遣先の対応として適切なものはどれか。派遣労働者は期間制限の例外に当たらないものとする。','[{"id":"a","text":"業務に密接に関連した教育訓練を，同じ業務を行う派遣先の正社員だけに実施した。"},{"id":"b","text":"工場で3年間働いていた派遣労働者を，今年から派遣を受け入れ始めた会社で正社員として受け入れた。"},{"id":"c","text":"事業環境に特に変化がなかったので，特段の対応をせず，同じ工場内で派遣労働者を4年間継続して受け入れた。"},{"id":"d","text":"ソフトウェア開発業務なので，派遣契約では期間制限を設けないルールとした。"}]','"b"','派遣労働者を直接雇用することは可能であり，期間制限の例外でない派遣受入れには法定の期間制限がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-38','exam-sg','ISMS・内部監査','standard','single_choice','【平成30年度 春期 午前 問38】JIS Q 27001:2014に準拠してISMSを運用している場合，内部監査について順守すべき要求事項はどれか。','[{"id":"a","text":"監査員にはISMS認証機関が認定する研修の修了者を含めなければならない。"},{"id":"b","text":"監査責任者は代表取締役が任命しなければならない。"},{"id":"c","text":"監査範囲はJIS Q 27001に規定された管理策に限定しなければならない。"},{"id":"d","text":"監査プログラムは前回までの監査結果を考慮しなければならない。"}]','"d"','内部監査プログラムを計画する際には，過去の監査結果や対象プロセスの重要性などを考慮する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-39','exam-sg','システム監査・監査証拠','standard','single_choice','【平成30年度 春期 午前 問39】システム監査において，監査証拠となるものはどれか。','[{"id":"a","text":"システム監査チームが監査意見を取りまとめるためのミーティング議事録"},{"id":"b","text":"システム監査チームが監査報告書に記載した指摘事項"},{"id":"c","text":"システム監査チームが作成した個別監査計画書"},{"id":"d","text":"システム監査チームが被監査部門から入手したシステム運用記録"}]','"d"','被監査部門から入手した運用記録は，監査人の判断を裏付ける監査証拠となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-40','exam-sg','システム監査・被監査部門の対応','standard','single_choice','【平成30年度 春期 午前 問40】システム監査実施における被監査部門の行為として，適切なものはどれか。','[{"id":"a","text":"監査部門から提出を要求された証憑の中で存在しないものがあれば，過去に遡って作成する。"},{"id":"b","text":"監査部門から要求されたアンケート調査に回答し，監査の実施に先立って監査部門に送付する。"},{"id":"c","text":"システム監査で調査すべき監査項目を自ら整理してチェックリストを作成し，それに基づく監査の実施を依頼する。"},{"id":"d","text":"被監査部門の情報システムが抱えている問題を基にして，自ら監査テーマを設定する。"}]','"b"','被監査部門は監査に必要な情報提供やアンケートへの回答などに協力する。証憑を遡って作成することは不適切。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
